    id: "bispecific-adc", dependsOn: ["adc", "bispecific-antibody"], links: [{"label":"ClinicalTrials.gov NCT06382142: BL-B01D1-307","url":"https://clinicaltrials.gov/study/NCT06382142"},{"label":"ClinicalTrials.gov NCT06304974: PANKU-Esophagus01 (BL-B01D1-305)","url":"https://clinicaltrials.gov/study/NCT06304974"},{"label":"BCG033 PTK7-by-TROP2 conjugates: preclinical AACR abstract (2024)","url":"https://doi.org/10.1158/1538-7445.am2024-2616"},{"label":"Li et al.: biparatopic HER2 conjugate in preclinical models (2016)","url":"https://pubmed.ncbi.nlm.nih.gov/26766593/"},{"label":"Andreev et al.: HER2 and prolactin-receptor trafficking experiments (2017)","url":"https://pubmed.ncbi.nlm.nih.gov/28108597/"}], kind: "technology", name: "Bispecific ADC", sections: ["adcs"], status: "phase-3",  since: 2023, generation: "4th (next-gen)",
    tldr: "A bispecific antibody-drug conjugate uses two recognition features to deliver a payload. Its design can change delivery; phase 3 testing still evaluates the complete drug.",
